INSERT INTO _demo_ql (seq, email, user_question, sub_question, user_text, sub_question_index, normalized_question, llm_question, ranking_eligible, region, offset_sec) VALUES
    (1, 'ubot.demo.186@example.test', '불만을 접수하고 싶은데 방법이 있나요?', '불만을 접수하고 싶은데 방법이 있나요?', '불만을 접수하고 싶은데 방법이 있나요?', 1, '불만을 접수하고 싶은데 방법이 있나요', '불만을 접수하고 싶으시면 Ubot 앱 또는 홈페이지의 고객의 소리 메뉴에서 접수할 수 있습니다. 접수한 내용의 처리 결과는 문자와 이메일로 알려 드립니다. 급한 불편이 있다면 고객센터(114)로 연락해 주세요.', true, 'GYEONGGI', -79215.335727),
    (2, 'ubot.demo.113@example.test', '유심을 다른 걸로 바꿔도 전화번호가 바뀌지 않나요?', '유심을 다른 걸로 바꿔도 전화번호가 바뀌지 않나요?', '유심을 다른 걸로 바꿔도 전화번호가 바뀌지 않나요?', 1, '유심을 다른 걸로 바꿔도 전화번호가 바뀌지 않나요', '유심을 다른 걸로 바꿔도 전화번호는 바뀌지 않습니다. 유심만 교체하는 경우 기존 전화번호는 그대로 유지됩니다.', true, 'SEOUL', -78644.016158),
    (3, 'ubot.demo.149@example.test', '해지하면 남은 단말 할부금은 어떻게 되나요?', '해지하면 남은 단말 할부금은 어떻게 되나요?', '해지하면 남은 단말 할부금은 어떻게 되나요?', 1, '해지하면 남은 단말 할부금은 어떻게 되나요', '해지하면 남은 단말 할부금은 원래 일정대로 매월 청구됩니다. 해지하면서 단말 할부금을 한 번에 정리하려면 매장이나 고객센터에서 남은 할부금을 일시 납부할 수 있습니다.', true, 'GWANGJU', -77989.917489),
    (4, 'ubot.demo.137@example.test', '해외에서 쓴 로밍 요금이 뒤늦게 청구된 건 오류인가요?', '해외에서 쓴 로밍 요금이 뒤늦게 청구된 건 오류인가요?', '해외에서 쓴 로밍 요금이 뒤늦게 청구된 건 오류인가요?', 1, '해외에서 쓴 로밍 요금이 뒤늦게 청구된 건 오류인가요', '해외에서 쓴 로밍 요금이 뒤늦게 청구된 것은 오류가 아니라 정상적인 사항입니다. 해외 통신사와 정산하는 과정에서 로밍 요금은 사용 후 1~2개월 뒤에 청구될 수 있습니다. 이는 통신사의 정책에 따라 발생하는 일반적인 현상입니다.', true, 'GYEONGGI', -77600.857998),
    (5, 'ubot.demo.173@example.test', '해외 로밍 사용 요금이 다음다음 달에 청구됐어요.', '해외 로밍 사용 요금이 다음다음 달에 청구됐어요.', '해외 로밍 사용 요금이 다음다음 달에 청구됐어요.', 1, '해외 로밍 사용 요금이 다음다음 달에 청구됐어요', '해외 로밍 요금은 해외 통신사와 정산하는 과정에서 1~2개월 뒤에 청구될 수 있습니다. 사용자의 경우 2026년 9월 청구서(8월 사용분)에는 로밍 요금이 0원으로 기재되어 있으며, 이는 해당 달에 해외 로밍 사용이 없었음을 의미합니다. 따라서 다음 달에 청구된 로밍 요금은 이전 달의 사용이 있었을 가능성이 있으며, 사용 내역을 앱에서 확인해야 합니다.', true, 'BUSAN', -77050.536015),
    (6, 'ubot.demo.126@example.test', '해지할 때 남은 단말 할부금은 어떻게 정산되나요?', '해지할 때 남은 단말 할부금은 어떻게 정산되나요?', '해지할 때 남은 단말 할부금은 어떻게 정산되나요?', 1, '해지할 때 남은 단말 할부금은 어떻게 정산되나요', '해지할 때 남은 단말 할부금은 원래 일정대로 매월 청구됩니다. 해지하면서 한 번에 정리하고 싶다면 고객센터(114)나 매장에서 남은 할부금을 일시 납부할 수 있습니다.', true, 'DAEGU', -76488.185049),
    (7, 'ubot.demo.129@example.test', '문의한 내용은 언제쯤 답을 받나요?', '문의한 내용은 언제쯤 답을 받나요?', '문의한 내용은 언제쯤 답을 받나요?', 1, '문의한 내용은 언제쯤 답을 받나요', '문의한 내용에 대한 답변은 고객센터 상담원이 평일 오전 9시부터 오후 6시까지 운영 중인 Ubot 고객센터에서 제공됩니다. 114 자동응답이나 Ubot 앱을 통해 24시간 문의 가능하지만, 답변은 상담원이 직접 처리하는 시간대에만 이루어집니다.', true, 'SEOUL', -76081.144077),
    (8, 'ubot.demo.110@example.test', '요금 관련해서 자주 하는 실수가 있나요?', '요금 관련해서 자주 하는 실수가 있나요?', '요금 관련해서 자주 하는 실수가 있나요?', 1, '요금 관련해서 자주 하는 실수가 있나요', '요금 관련 실수 예시로는 청구서의 납부 기한을 넘기거나, 사용량과 요금제의 제한을 잘못 이해하는 경우가 있습니다. 예를 들어, Ubot 베이직 55 요금제는 월정액 55,000원이며, 데이터 13.7GB를 제공하지만 소진 후 최대 1Mbps로 제한됩니다. 사용자가 데이터 사용량을 초과하거나, 음성·문자 사용량에 대한 제한을 잘못 인지하면 비용 부담이 증가할 수 있습니다. 또한, 최근 청구서(2026년 10월)는 총 62,450원으로, 기본료 55,000원과 부가서비스 요금(7,450원)이 포함되어 있으며, 납부 기한이 2026-10-25까지였습니다. 이 기한을 넘기면 미납으로 처리되어 추가로 지불이 필요합니다. 따라서 요금제의 내용과 청구서 납부 기한을 정확히 파악하는 것이 중요합니다.', true, 'DAEGU', -75439.022075),
    (9, 'ubot.demo.119@example.test', '해외 로밍 요금이 한참 지나서 나오는 게 정상인가요?', '해외 로밍 요금이 한참 지나서 나오는 게 정상인가요?', '해외 로밍 요금이 한참 지나서 나오는 게 정상인가요?', 1, '해외 로밍 요금이 한참 지나서 나오는 게 정상인가요', '예, 해외 로밍 요금이 한참 뒤에 청구되는 것은 정상입니다. 해외 통신사와 정산하는 과정에서 1~2개월 뒤에 요금이 청구될 수 있으며, 이는 일반적인 사항입니다. 사용 날짜는 앱의 로밍 이용 내역에서 확인할 수 있습니다.', true, 'GWANGJU', -74864.294912),
    (10, 'ubot.demo.162@example.test', '해외 로밍 요금이 늦게 청구돼서 당황했어요.', '해외 로밍 요금이 늦게 청구돼서 당황했어요.', '해외 로밍 요금이 늦게 청구돼서 당황했어요.', 1, '해외 로밍 요금이 늦게 청구돼서 당황했어요', '해외 로밍 요금은 해외 통신사와 정산하는 데 시간이 걸려 사용 후 1~2개월 뒤에 청구될 수 있습니다. 사용 날짜는 앱의 로밍 이용 내역에서 확인할 수 있습니다.', true, 'DAEJEON', -74275.037244),
    (11, 'ubot.demo.153@example.test', '해지 후에도 단말 할부금이 남아 있으면 어떻게 되나요?', '해지 후에도 단말 할부금이 남아 있으면 어떻게 되나요?', '해지 후에도 단말 할부금이 남아 있으면 어떻게 되나요?', 1, '해지 후에도 단말 할부금이 남아 있으면 어떻게 되나요', '해지 후에도 남은 단말 할부금은 원래 일정대로 매월 청구됩니다. 해지하면서 단말 할부금을 한 번에 정리하려면 고객센터(114)나 매장에서 남은 할부금을 일시 납부할 수 있습니다.', true, 'INCHEON', -73963.361875),
    (12, 'ubot.demo.105@example.test', '해외에서 쓴 로밍 요금이 한참 뒤에 한꺼번에 청구됐어요.', '해외에서 쓴 로밍 요금이 한참 뒤에 한꺼번에 청구됐어요.', '해외에서 쓴 로밍 요금이 한참 뒤에 한꺼번에 청구됐어요.', 1, '해외에서 쓴 로밍 요금이 한참 뒤에 한꺼번에 청구됐어요', '해외 로밍 요금은 해외 통신사와 정산하는 데 시간이 걸려 사용 후 1~2개월 뒤에 청구될 수 있습니다. 사용 날짜는 앱의 로밍 이용 내역에서 확인할 수 있습니다. 그러나 현재 이용 중인 회선에 로밍이 설정되어 있지 않으며, 최근 청구서에도 로밍 요금이 포함되지 않았습니다. 따라서 해외에서 쓴 로밍 요금이 한참 뒤에 청구된 것은 가능하지만, 해당 회선의 로밍 이용 내역이 없어 구체적인 사항을 확인할 수 없습니다.', true, 'GWANGJU', -73359.231185),
    (13, 'ubot.demo.108@example.test', '유심 교체하면 내 전화번호도 바뀌나요?', '유심 교체하면 내 전화번호도 바뀌나요?', '유심 교체하면 내 전화번호도 바뀌나요?', 1, '유심 교체하면 내 전화번호도 바뀌나요', '유심을 교체하는 경우 기존 전화번호는 그대로 유지됩니다.', true, 'BUSAN', -72891.004468),
    (14, 'ubot.demo.198@example.test', '유심을 바꾸면 기존 전화번호가 변경되나요?', '유심을 바꾸면 기존 전화번호가 변경되나요?', '유심을 바꾸면 기존 전화번호가 변경되나요?', 1, '유심을 바꾸면 기존 전화번호가 변경되나요', '문의하신 내용은 현재 안내 자료로는 확인해 드리기 어렵습니다.', true, 'GWANGJU', -72122.730801),
    (15, 'ubot.demo.115@example.test', '해지하려는데 남은 단말 할부금은 어떻게 되는지 궁금해요.', '해지하려는데 남은 단말 할부금은 어떻게 되는지 궁금해요.', '해지하려는데 남은 단말 할부금은 어떻게 되는지 궁금해요.', 1, '해지하려는데 남은 단말 할부금은 어떻게 되는지 궁금해요', '해지하면 남은 단말 할부금은 원래 일정대로 매월 청구됩니다. 해지하면서 단말 할부금을 한 번에 정리하려면 매장이나 고객센터에서 남은 할부금을 일시 납부할 수 있습니다.', true, 'SEOUL', -71623.419199),
    (16, 'ubot.demo.163@example.test', '유심을 교체하면 전화번호도 변경되나요?', '유심을 교체하면 전화번호도 변경되나요?', '유심을 교체하면 전화번호도 변경되나요?', 1, '유심을 교체하면 전화번호도 변경되나요', '유심을 교체하는 경우 기존 전화번호는 그대로 유지됩니다.', true, 'GWANGJU', -71296.512822),
    (17, 'ubot.demo.135@example.test', '온라인으로도 문의할 수 있나요?', '온라인으로도 문의할 수 있나요?', '온라인으로도 문의할 수 있나요?', 1, '온라인으로도 문의할 수 있나요', '네, 온라인으로 문의할 수 있습니다. 고객센터 대표번호에서 상담원 연결 메뉴를 선택하면 상담원과 직접 통화할 수 있으며, 이는 온라인 환경에서도 가능합니다.', true, 'GWANGJU', -70456.958935),
    (18, 'ubot.demo.136@example.test', '유심 교체하면 내 전화번호도 변경되나요?', '유심 교체하면 내 전화번호도 변경되나요?', '유심 교체하면 내 전화번호도 변경되나요?', 1, '유심 교체하면 내 전화번호도 변경되나요', '유심을 교체하는 경우 기존 전화번호는 그대로 유지됩니다.', true, 'SEOUL', -69925.839229),
    (19, 'ubot.demo.107@example.test', '회선을 해지하면 남은 단말기 할부금은 어떻게 하나요?', '회선을 해지하면 남은 단말기 할부금은 어떻게 하나요?', '회선을 해지하면 남은 단말기 할부금은 어떻게 하나요?', 1, '회선을 해지하면 남은 단말기 할부금은 어떻게 하나요', '회선을 해지해도 남은 단말기 할부금은 계속 납부해야 합니다. 해지하면서 단말 할부금을 한 번에 정리하려면 매장이나 고객센터에서 남은 할부금을 일시 납부할 수 있습니다.', true, 'GYEONGGI', -69489.206172),
    (20, 'ubot.demo.102@example.test', '해외에서 쓴 로밍 요금이 늦게 청구되는 건 원래 그런가요?', '해외에서 쓴 로밍 요금이 늦게 청구되는 건 원래 그런가요?', '해외에서 쓴 로밍 요금이 늦게 청구되는 건 원래 그런가요?', 1, '해외에서 쓴 로밍 요금이 늦게 청구되는 건 원래 그런가요', '예, 해외에서 쓴 로밍 요금이 늦게 청구되는 것은 원래 그런 것입니다. 해외 통신사와 정산하는 과정이 필요하기 때문에 사용 후 1~2개월 뒤에 청구되는 경우가 많습니다. 사용한 다음 달이나 그다음 달에 청구되는 것이 일반적입니다.', true, 'INCHEON', -68964.824909),
    (21, 'ubot.demo.157@example.test', '멤버십 혜택을 어디서 확인하나요?', '멤버십 혜택을 어디서 확인하나요?', '멤버십 혜택을 어디서 확인하나요?', 1, '멤버십 혜택을 어디서 확인하나요', 'Ubot 앱의 멤버십 메뉴에서 현재 멤버십 등급과 남은 혜택 횟수를 확인할 수 있습니다.', true, 'GYEONGGI', -68575.607004),
    (22, 'ubot.demo.168@example.test', '등급 기준이 어떻게 되는지 궁금해요.', '등급 기준이 어떻게 되는지 궁금해요.', '등급 기준이 어떻게 되는지 궁금해요.', 1, '등급 기준이 어떻게 되는지 궁금해요', '문의하신 내용은 현재 안내 자료로는 확인해 드리기 어렵습니다.', true, 'DAEGU', -68084.760987),
    (23, 'ubot.demo.138@example.test', '고객센터 운영 방식이 어떻게 되나요?', '고객센터 운영 방식이 어떻게 되나요?', '고객센터 운영 방식이 어떻게 되나요?', 1, '고객센터 운영 방식이 어떻게 되나요', '고객센터 상담원은 평일 오전 9시부터 오후 6시까지 연결이 가능합니다. 분실 신고와 요금 조회·납부는 114 자동응답이나 Ubot 앱에서 24시간 이용할 수 있습니다.', true, 'INCHEON', -67382.696809),
    (24, 'ubot.demo.113@example.test', '영상을 보는데 갑자기 데이터가 너무 느려졌어요.', '영상 플레이 중 데이터 속도가 느려지는 현상은 어떻게 해결할 수 있나요?', NULL, 2, '영상을 보는데 갑자기 데이터가 너무 느려졌어요', '영상을 보는데 데이터 속도가 갑자기 느려졌다면, 데이터 제공량을 소진했거나 네트워크가 혼잡할 수 있습니다.', true, 'SEOUL', -66996.944562),
    (25, 'ubot.demo.113@example.test', '영상을 보는데 갑자기 데이터가 너무 느려졌어요.', '데이터 속도가 느려지는 문제는 서비스 제공사에서 어떤 조치를 취하고 있나요?', NULL, 3, '영상을 보는데 갑자기 데이터가 너무 느려졌어요', '영상을 보는데 데이터 속도가 갑자기 느려졌다면, 데이터 제공량을 소진했거나 네트워크가 혼잡할 수 있습니다.', true, 'SEOUL', -66996.944562),
    (26, 'ubot.demo.174@example.test', '요금이 갑자기 올랐다는 느낌이 들 때 확인할 것이 있나요?', '요금이 갑자기 올랐다는 느낌이 들 때 확인할 것이 있나요?', '요금이 갑자기 올랐다는 느낌이 들 때 확인할 것이 있나요?', 1, '요금이 갑자기 올랐다는 느낌이 들 때 확인할 것이 있나요', '요금이 평소보다 많이 나왔다면 앱의 요금 상세 내역에서 데이터 추가 사용, 로밍, 휴대폰 결제, 부가서비스, 단말 할부금 항목을 확인해 주세요. 월 중간에 요금제를 바꿨다면 두 요금제의 요금이 날짜별로 나뉘어 청구돼 평소와 달라 보일 수 있습니다. 사용자 정보에 따르면, 2026년 9월 청구서(8월 사용분)는 기본료 99,000원, 부가서비스 550원, 할인 24,750원을 적용한 총 74,800원으로, 이전 달과 동일한 금액이므로 요금이 갑자기 올랐다고 느껴질 수 있는 이유는 없으며, 최근 사용량(2026-10)과 청구서(2026-10)도 평소와 비슷한 수준을 유지하고 있습니다.', true, 'INCHEON', -66418.132931),
