    (1, 'SEOUL', '서울 지역 모바일 데이터 속도 저하', 10, 10, -27000.0, -26999.687828),
    (2, 'SEOUL', '서울 지역 IPTV 신호 없음 문의 급증', 10, 10, -18600, -18599.698915),
    (3, 'SEOUL', '서울 지역 본인인증 문자 급증', 10, 10, -13200, -13199.726617),
    (4, 'GYEONGGI', '경기 지역 통신 장애 문의 급증', 10, 10, -8100, -8099.493554),
