INSERT INTO _demo_alert_q (alert_seq, pos, ql_seq, question) VALUES
    (1, 1, 101, '데이터 속도가 갑자기 느려졌어요.'),
    (1, 2, 102, '휴대폰 데이터 속도가 갑자기 느려졌는데 왜 그런가요?'),
    (1, 3, 103, '모바일 인터넷이 갑자기 느려졌어요.'),
    (1, 4, 104, '갑자기 모바일 데이터 속도가 떨어진 이유가 뭔가요?'),
    (1, 5, 105, '데이터 연결 속도가 갑자기 떨어졌습니다.'),
    (1, 6, 106, '휴대폰 데이터가 전보다 갑자기 느려요.'),
    (1, 7, 107, '데이터가 갑자기 느려졌을 때 해결 방법은 무엇인가요?'),
    (1, 8, 108, '모바일 인터넷이 평소보다 많이 느린데 원인이 뭘까요?'),
    (1, 9, 109, '데이터 속도가 급격히 줄었는데 서비스 점검이 진행 중인가요?'),
    (1, 10, 110, 'LTE 속도가 갑자기 안 나오는 이유를 알고 싶어요.'),
    (2, 1, 136, 'IPTV에서 신호 없음 화면이 나와요.'),
    (2, 2, 137, 'IPTV에 신호 없음이라고 뜨면 어떻게 하나요?'),
    (2, 3, 138, '셋톱박스를 케이트했는데 TV에 신호가 없다고 나와요. 이 문제는 어떻게 해결할 수 있나요?'),
    (2, 4, 139, '텔레비전에 HDMI 신호가 없다고 표시돼요.'),
    (2, 5, 140, 'IPTV 대신 외부 입력 신호 없음 문구만 보여요.'),
    (2, 6, 141, '셋톱 연결 화면이 신호 없음 상태에서 안 바뀌어요.'),
    (2, 7, 142, 'TV에서 신호 없음 화면이 계속 나오는 경우 해결 방법은 무엇인가요?'),
    (2, 8, 143, '셋톱박스에서 신호가 없다고 뜨는 이유가 뭔가요?'),
    (2, 9, 144, 'IPTV 화면이 안 나오고 신호 없음만 떠요.'),
    (2, 10, 145, 'TV를 켰더니 신호 없음이라는 글자만 보여요.'),
    (3, 1, 165, '본인인증 문자가 오지 않아요.'),
    (3, 2, 166, '인증번호 문자가 안 와요.'),
