BEGIN;
SET LOCAL client_encoding = 'UTF8';
SET LOCAL TIME ZONE 'Asia/Seoul';

CREATE TEMP TABLE _demo_base ON COMMIT DROP AS SELECT LOCALTIMESTAMP AS now_ts;

CREATE TEMP TABLE _demo_ql (
    seq INTEGER PRIMARY KEY,
    email TEXT NOT NULL,
    user_question TEXT NOT NULL,
    sub_question TEXT,
    user_text TEXT,
    sub_question_index SMALLINT NOT NULL,
    normalized_question TEXT NOT NULL,
    llm_question TEXT NOT NULL,
    ranking_eligible BOOLEAN NOT NULL,
    region VARCHAR(20),
    offset_sec DOUBLE PRECISION NOT NULL,
    created_at TIMESTAMP
) ON COMMIT DROP;
