    (120, 'ubot.demo.120@example.test', '퇴근 시간에 갑자기 데이터 속도가 너무 느려졌어요.', '퇴근 시간에 갑자기 데이터 속도가 너무 느려졌어요.', '퇴근 시간에 갑자기 데이터 속도가 너무 느려졌어요.', 1, '퇴근 시간에 갑자기 데이터 속도가 너무 느려졌어요', '퇴근 시간에 갑자기 데이터 속도가 너무 느려졌다면 데이터 제공량을 소진했거나 네트워크가 혼잡할 수 있습니다.', true, 'SEOUL', -26971.742964),
    (121, 'ubot.demo.120@example.test', '해지해도 단말 할부금은 계속 내야 하나요?', '해지해도 단말 할부금은 계속 내야 하나요?', '해지해도 단말 할부금은 계속 내야 하나요?', 1, '해지해도 단말 할부금은 계속 내야 하나요', '해지해도 남은 단말 할부금은 계속 청구됩니다. 휴대폰 회선을 해지해도 남은 할부금은 원래 일정대로 매월 납부되어야 하며, 한 번에 정리하려면 매장이나 고객센터에서 일시 납부할 수 있습니다.', true, 'SEOUL', -26682.760329),
    (122, 'ubot.demo.140@example.test', '요금이 지난달보다 올랐는데 이유를 알 수 있나요?', '요금이 지난달보다 올랐는데 이유를 알 수 있나요?', '요금이 지난달보다 올랐는데 이유를 알 수 있나요?', 1, '요금이 지난달보다 올랐는데 이유를 알 수 있나요', '요금이 지난달보다 올랐다는 점을 확인해 보니, 2026년 9월 청구서(8월 사용분) 기준으로는 총 76,350원이 청구되었고, 이는 2026년 10월 청구서(9월 사용분) 기준의 76,350원과 동일한 금액입니다. 따라서 요금이 지난달보다 올랐다고 느끼는 것은 청구 금액이 실제로 증가했음을 의미하지 않습니다. 다만, 2026년 9월 청구서는 연체 상태였으며, 이로 인해 사용자에게 불편함을 줄 수 있습니다. 요금이 평소보다 많이 나왔다고 느끼는 경우는 데이터 추가 사용, 로밍, 부가서비스, 단말 할부금 등 항목을 확인해 보시는 것이 좋습니다.', true, 'DAEJEON', -26030.647774),
    (123, 'ubot.demo.111@example.test', '해외에서 사용한 로밍 요금이 몇 주나 지나서 청구됐어요.', '해외에서 사용한 로밍 요금이 몇 주나 지나서 청구됐어요.', '해외에서 사용한 로밍 요금이 몇 주나 지나서 청구됐어요.', 1, '해외에서 사용한 로밍 요금이 몇 주나 지나서 청구됐어요', '해외에서 사용한 로밍 요금은 해외 통신사와 정산하는 과정 때문에 사용 후 1~2개월 뒤에 청구될 수 있습니다. 따라서 몇 주나 지나서 청구된 것은 정상적인 사항입니다.', true, 'INCHEON', -25567.847146),
    (124, 'ubot.demo.154@example.test', '요금 내역을 엑셀 같은 걸로 받을 수 있나요?', '요금 내역을 엑셀 같은 걸로 받을 수 있나요?', '요금 내역을 엑셀 같은 걸로 받을 수 있나요?', 1, '요금 내역을 엑셀 같은 걸로 받을 수 있나요', '문의하신 내용은 현재 안내 자료로는 확인해 드리기 어렵습니다.', true, 'DAEJEON', -25004.864819),
    (125, 'ubot.demo.200@example.test', '문제가 생겼는데 어디에 말해야 하나요?', '문제가 생겼을 때 어디에 문의해야 하나요?', '문제가 생겼는데 어디에 말해야 하나요?', 1, '문제가 생겼는데 어디에 말해야 하나요', '문제가 생기면 휴대폰 분실·도난인 경우, 고객센터 자동응답, 앱 또는 홈페이지에서 24시간 365일 신고할 수 있습니다. 해외에서 휴대이나 경우 +82-2-1500-0000으로 연락해 주세요.', true, 'GYEONGGI', -24305.20112),
    (126, 'ubot.demo.134@example.test', '고객센터 말고 앱으로도 상담이 되나요?', '앱으로 상담이 가능한가요?', '고객센터 말고 앱으로도 상담이 되나요?', 1, '고객센터 말고 앱으로도 상담이 되나요', '앱을 통해 상담이 가능하지 않습니다. 상담원과의 직접 통화는 고객센터 대표번호에서만 가능하며, 앱을 통해 상담이 되는 경우는 없습니다.', true, 'GWANGJU', -23921.567895),
    (127, 'ubot.demo.142@example.test', '해지하면 남은 단말 할부금은 한꺼번에 내야 하나요?', '해지하면 남은 단말 할부금은 한꺼번에 내야 하나요?', '해지하면 남은 단말 할부금은 한꺼번에 내야 하나요?', 1, '해지하면 남은 단말 할부금은 한꺼번에 내야 하나요', '해지하면 남은 단말 할부금을 한꺼번에 내야 한다는 것은 아닙니다. 휴대폰 회선을 해지해도 남은 단말 할부금은 원래 일정대로 매월 청구됩니다. 다만, 매장이나 고객센터에서 남은 할부금을 한 번에 납부할 수 있으므로, 해지 시 한 번에 정리하고 싶다면 해당 서비스를 이용할 수 있습니다.', true, 'GWANGJU', -23355.576852),
    (128, 'ubot.demo.141@example.test', '청구서 항목 중에 모르는 게 있어요.', '청구서 항목 중에 모르는 게 있어요.', '청구서 항목 중에 모르는 게 있어요.', 1, '청구서 항목 중에 모르는 게 있어요', '청구서 항목 중 모르는 부분이 있다면, 2026년 9월 청구서(8월 사용분)를 확인해 보세요. 이 청구서는 기본료 55,000원, 부가서비스 0원, 로밍 0원, 기타 0원, 할인 -13,750원으로 구성되어 있으며, 총 요금은 41,250원입니다. 요금제는 Ubot 데이터 14GB로, 월정액이 55,000원이며, 약정 할인 13,750원이 적용되어 있습니다. 이 항목들은 사용자 정보와 일치합니다. 만약 특정 항목이 불분명하다면, 청구서 세부 내역을 확인하거나 이전 통신사에 문의해 주세요.', true, 'GWANGJU', -22724.820918),
    (129, 'ubot.demo.152@example.test', '요금 미납 문자를 받았는데 어떻게 해야 하나요?', '요금 미납 문자를 받았을 때 어떻게 해야 하나요?', '요금 미납 문자를 받았는데 어떻게 해야 하나요?', 1, '요금 미납 문자를 받았는데 어떻게 해야 하나요', '요금 미납 문자를 받았다면, 즉시 미납 요금을 납부해야 합니다. Ubot 앱 또는 홈페이지에서 즉시 납부, 또는 청구서 및 문자에 안내된 가상계좌로 입금할 수 있습니다. 납부 후 서비스는 바로 다시 이용 가능합니다.', true, 'INCHEON', -22408.26487),
    (130, 'ubot.demo.179@example.test', '로밍을 쓴 지 한참 뒤에 요금이 청구됐어요.', '로밍을 쓴 지 한참 뒤에 요금이 청구됐어요.', '로밍을 쓴 지 한참 뒤에 요금이 청구됐어요.', 1, '로밍을 쓴 지 한참 뒤에 요금이 청구됐어요', '로밍을 쓴 지 한참 뒤에 요금이 청구됐어요. 해외 로밍 요금은 해외 통신사와 정산하는 데 시간이 걸려 사용 후 1~2개월 뒤에 청구될 수 있습니다. 사용 날짜는 앱의 로밍 이용 내역에서 확인할 수 있습니다.', true, 'GYEONGGI', -21880.770299),
    (131, 'ubot.demo.170@example.test', '포인트로 요금을 낼 수 있나요?', '포인트로 요금을 낼 수 있나요?', '포인트로 요금을 낼 수 있나요?', 1, '포인트로 요금을 낼 수 있나요', '예, 포인트로 요금을 낼 수 있습니다. Ubot 포인트는 청구된 요금 전체에 적용되며, 부가서비스 요금도 포함한 청구 요금 납부에 월 최대 5,000포인트까지 사용할 수 있습니다.', true, 'SEOUL', -21101.12395),
    (132, 'ubot.demo.159@example.test', '유심을 바꾸면 전화번호도 바뀌나요?', '유심을 바꾸면 전화번호도 바뀌나요?', '유심을 바꾸면 전화번호도 바뀌나요?', 1, '유심을 바꾸면 전화번호도 바뀌나요', '유심을 바꾸는 경우 전화번호는 바뀌지 않습니다. 기존 전화번호는 그대로 유지됩니다.', true, 'BUSAN', -20593.573168),
    (133, 'ubot.demo.140@example.test', '유심을 바꾸면 기존 전화번호가 바뀌나요?', '유심을 바꾸면 기존 전화번호가 바뀌나요?', '유심을 바꾸면 기존 전화번호가 바뀌나요?', 1, '유심을 바꾸면 기존 전화번호가 바뀌나요', '유심을 바꾸는 경우 기존 전화번호는 바뀌지 않습니다. 유심이나 eSIM을 바꿔도 전화번호는 그대로 유지됩니다.', true, 'DAEGU', -20239.85536),
    (134, 'ubot.demo.156@example.test', '납부 확인서가 필요한데 어떻게 받나요?', '납부 확인서가 필요한데 어떻게 받나요?', '납부 확인서가 필요한데 어떻게 받나요?', 1, '납부 확인서가 필요한데 어떻게 받나요', '납부 확인서는 Ubot 앱 또는 홈페이지에서 최근 5년 치까지 바로 발급받을 수 있습니다. 해지한 회선의 납부 확인서는 신분증을 가지고 매장을 방문하거나 고객센터에 요청해야 합니다.', true, 'SEOUL', -19722.345826),
    (135, 'ubot.demo.129@example.test', '상담원 연결 번호를 알려주세요.', '상담원 연결 번호를 알려주세요.', '상담원 연결 번호를 알려주세요.', 1, '상담원 연결 번호를 알려주세요', '상담원과 연결하려면 Ubot 휴대폰에서 114로 전화한 뒤 안내에 따라 상담원 연결을 선택하면 됩니다.', true, 'GYEONGGI', -19008.60986),
    (136, 'ubot.demo.141@example.test', 'IPTV에서 신호 없음 화면이 나와요.', 'IPTV에서 신호 없음 화면이 나와요.', 'IPTV에서 신호 없음 화면이 나와요.', 1, 'iptv에서 신호 없음 화면이 나와요', 'IPTV에서 신호 없음 화면이 나오면 TV 외부 입력이 셋톱박스가 연결된 HDMI로 선택됐는지 확인하세요. IPTV 신호가 없으면 셋톱박스 전원과 HDMI 케이블 연결도 점검해 주세요. 신호 없음 문제가 계속되면 다른 케이블이나 단자로 비교한 뒤 고객센터에 문의하세요.', true, 'SEOUL', -18636.689751),
    (137, 'ubot.demo.142@example.test', 'IPTV에 신호 없음이라고 뜨면 어떻게 하나요?', 'IPTV에 신호 없음이라고 뜨면 어떻게 하나요?', 'IPTV에 신호 없음이라고 뜨면 어떻게 하나요?', 1, 'iptv에 신호 없음이라고 뜨면 어떻게 하나요', 'IPTV에서 신호 없음 화면이 나오면 TV 외부 입력이 셋톱박스가 연결된 HDMI로 선택됐는지 확인하세요. IPTV 신호가 없으면 셋톱박스 전원과 HDMI 케이블 연결도 점검해 주세요. 신호 없음 문제가 계속되면 다른 케이블이나 단자로 비교한 뒤 고객센터에 문의하세요.', true, 'SEOUL', -18632.808246),
    (138, 'ubot.demo.143@example.test', '셋톱박스를 켰는데 TV에 신호가 없다고 나와요.', '셋톱박스를 케이트했는데 TV에 신호가 없다고 나와요. 이 문제는 어떻게 해결할 수 있나요?', '셋톱박스를 켰는데 TV에 신호가 없다고 나와요.', 1, '셋톱박스를 켰는데 tv에 신호가 없다고 나와요', '셋톱박스를 케이블로 연결한 후 TV의 외부 입력을 셋톱박스가 연결된 HDMI 포트로 설정했는지 확인해 주세요. 또한 셋톱박스 전원과 HDMI 케이블의 연결 상태를 점검해 주세요. 신호 없음 문제가 지속되면 다른 HDMI 케이블이나 단자로 교체한 후 고객센터에 문의해 주세요.', true, 'SEOUL', -18628.06438),
    (139, 'ubot.demo.144@example.test', '텔레비전에 HDMI 신호가 없다고 표시돼요.', '텔레비전에 HDMI 신호가 없다고 표시돼요.', '텔레비전에 HDMI 신호가 없다고 표시돼요.', 1, '텔레비전에 hdmi 신호가 없다고 표시돼요', '텔레비전에 HDMI 신호가 없다고 표시돼요면, IPTV에서 신호 없음 화면이 나오는 경우와 동일한 원인일 수 있습니다. 먼저 TV의 외부 입력 설정을 확인해 주세요. 셋톱박스가 연결된 HDMI 입력 채널이 선택되어 있는지 확인하고, 셋톱박스의 전원과 HDMI 케이블 연결 상태도 점검해 주세요. 신호가 계속 없으면 다른 HDMI 케이블이나 단자로 교체해 보고, 고객센터에 문의하시기 바랍니다.', true, 'SEOUL', -18624.452454),
    (140, 'ubot.demo.145@example.test', 'IPTV 대신 외부 입력 신호 없음 문구만 보여요.', 'IPTV 대신 외부 입력 신호 없음 문구만 보여요.', 'IPTV 대신 외부 입력 신호 없음 문구만 보여요.', 1, 'iptv 대신 외부 입력 신호 없음 문구만 보여요', '외부 입력 신호 없음 문구가 보이는 경우, TV의 외부 입력이 셋톱박스가 연결된 HDMI 포트로 설정되어 있는지 확인하세요. 설정이 틀리면 IPTV 신호가 정상적으로 출력되지 않아 외부 입력 신호 없음 화면이 나타날 수 있습니다. 셋톱박스 전원과 HDMI 케이블 연결 상태도 점검해 주세요. 문제가 지속되면 다른 HDMI 케이이나 단자로 연결해 비교한 후 고객센터에 문의하시기 바랍니다.', true, 'SEOUL', -18620.244265),
