    (154, 'ubot.demo.160@example.test', '셋톱박스 불은 들어오는데 TV에서는 신호 없음이라고 떠요.', '셋톱박스 불이 들어오는데 TV에서 ''신호 없음''이라고 떠야 하는 경우, 어떤 원인일 수 있나요?', '셋톱박스 불은 들어오는데 TV에서는 신호 없음이라고 떠요.', 1, '셋톱박스 불은 들어오는데 tv에서는 신호 없음이라고 떠요', '셋톱박스 전원은 들어오고 있지만 TV에서 신호 없음 화면이 나오면, TV의 외부 입력이 셋톱박스가 연결된 HDMI로 설정되어 있는지 확인하세요. 또한 셋톱박스와 TV 간의 HDMI 케이블 연결 상태를 점검해 주세요. 문제が 계속되면 다른 HDMI 케이블이나 단자로 교체한 후 고객센터에 문의하시기 바랍니다.', true, 'SEOUL', -18563.76544),
    (155, 'ubot.demo.181@example.test', '해지하면 단말 할부금이 남아 있을 때 어떻게 처리되나요?', '해지하면 단말 할부금이 남아 있을 때 어떻게 처리되나요?', '해지하면 단말 할부금이 남아 있을 때 어떻게 처리되나요?', 1, '해지하면 단말 할부금이 남아 있을 때 어떻게 처리되나요', '해지하면 남은 단말 할부금은 원래 일정대로 매월 청구됩니다. 해지하면서 한 번에 정리하고 싶다면 매장이나 고객센터에서 남은 할부금을 일시 납부할 수 있습니다.', true, 'INCHEON', -18407.15124),
    (156, 'ubot.demo.103@example.test', '서비스를 해지하면 남은 단말기 할부금은 누가 내나요?', '서비스를 해지하면 남은 단말기 할부금은 누가 내나요?', '서비스를 해지하면 남은 단말기 할부금은 누가 내나요?', 1, '서비스를 해지하면 남은 단말기 할부금은 누가 내나요', '서비스를 해지해도 남은 단말기 할부금은 고객이 계속 납부해야 합니다. 해지 후에도 할부금은 원래 일정대로 매월 청구되며, 고객이 직접 납부해야 합니다. 한 번에 납부하려면 고객센터 또는 매장에서 처리할 수 있습니다.', true, 'BUSAN', -18109.955368),
    (157, 'ubot.demo.148@example.test', '요금 할인이 적용됐는지 어디서 확인하나요?', '요금 할인이 적용됐는지 어디서 확인하나요?', '요금 할인이 적용됐는지 어디서 확인하나요?', 1, '요금 할인이 적용됐는지 어디서 확인하나요', '요금 할인이 적용됐는지 확인하기 위해서는 최근 청구서에 있는 ''할인'' 항목을 확인해야 합니다. 사용자 정보에 따르면, 2026년 10월 청구서 기준으로 ''할인 -0원''이 기재되어 있어 요금 할인이 적용되지 않았습니다. 요금제 변경 여부나 할인 적용 여부는 청구서 내부 항목에서 확인할 수 있으며, 앱 내 ''내 정보'' 메뉴에서 요금제와 청구서 상세 내용을 확인할 수 있습니다.', true, 'GWANGJU', -17330.548087),
    (158, 'ubot.demo.104@example.test', '추가 요금이 붙는 경우에는 어떤 게 있나요?', '추가 요금이 붙는 경우에는 어떤 게 있나요?', '추가 요금이 붙는 경우에는 어떤 게 있나요?', 1, '추가 요금이 붙는 경우에는 어떤 게 있나요', '문의하신 내용은 현재 안내 자료로는 확인해 드리기 어렵습니다.', true, 'INCHEON', -16815.69481),
    (159, 'ubot.demo.154@example.test', '멤버십 가입하면 좋은 점이 뭔가요?', '멤버십 가입하면 좋은 점이 뭔가요?', '멤버십 가입하면 좋은 점이 뭔가요?', 1, '멤버십 가입하면 좋은 점이 뭔가요', '문의하신 내용은 현재 안내 자료로는 확인해 드리기 어렵습니다.', true, 'DAEGU', -16368.698573),
    (160, 'ubot.demo.144@example.test', '요금 납부를 깜빡했을 때는 어떻게 되나요?', '요금 납부를 깜빡했을 때는 어떻게 되나요?', '요금 납부를 깜빡했을 때는 어떻게 되나요?', 1, '요금 납부를 깜빡했을 때는 어떻게 되나요', '요금 납부를 깜빡했을 때는 다음 날 미납 안내 문자가 발송되며, 미납 금액의 2%가 연체 가산금으로 한 번 청구됩니다. 다만, 2개월 이상 미납되면 전화 발신이 정지되고, 3개월 이상 미납되면 전화 수신까지 정지됩니다. 따라서 요금을 깜빡했을 경우, 즉시 확인하고 납부하여 서비스 정지가 발생하지 않도록 해야 합니다.', true, 'BUSAN', -15890.600102),
    (161, 'ubot.demo.183@example.test', '유심 칩을 바꾸면 전화번호도 바뀌는 건가요?', '유심 칩을 바꾸면 전화번호도 바뀌는 건가요?', '유심 칩을 바꾸면 전화번호도 바뀌는 건가요?', 1, '유심 칩을 바꾸면 전화번호도 바뀌는 건가요', '유심을 바꾸는 경우 전화번호는 바뀌지 않습니다. 기존 전화번호는 그대로 유지됩니다.', true, 'DAEJEON', -15456.151221),
    (162, 'ubot.demo.105@example.test', '해외에서 쓴 요금이 한참 지나서야 청구서에 나왔어요.', '해외에서 쓴 요금이 한참 지나서야 청구서에 나왔어요.', '해외에서 쓴 요금이 한참 지나서야 청구서에 나왔어요.', 1, '해외에서 쓴 요금이 한참 지나서야 청구서에 나왔어요', '해외에서 쓴 요금이 한참 지나서 청구서에 나왔다는 것은 로밍 요금이 해외 통신사와 정산하는 과정에서 1~2개월 뒤에 청구되는 경우입니다. 사용 후 다음 달이나 그다음 달에 청구되는 것이 일반적입니다.', true, 'DAEGU', -14940.3953),
    (163, 'ubot.demo.149@example.test', '요금제를 바꾸면 청구 금액이 언제부터 달라지나요?', '요금제를 바꾸면 청구 금액이 언제부터 달라지나요?', '요금제를 바꾸면 청구 금액이 언제부터 달라지나요?', 1, '요금제를 바꾸면 청구 금액이 언제부터 달라지나요', '요금제를 바꾸면 청구 금액은 변경 전후의 사용량을 각각 사용한 날짜만큼 나누어 다음 달 청구서에서 합산하여 확인할 수 있습니다. 바뀐 요금제 기준으로 계산된 요금은 다음 달 청구서에서 확인됩니다.', true, 'SEOUL', -14106.099709),
    (164, 'ubot.demo.184@example.test', '해외에서 쓴 로밍 요금이 왜 한참 뒤에 청구되나요?', '해외에서 쓴 로밍 요금이 왜 한참 뒤에 청구되나요?', '해외에서 쓴 로밍 요금이 왜 한참 뒤에 청구되나요?', 1, '해외에서 쓴 로밍 요금이 왜 한참 뒤에 청구되나요', '해외에서 쓴 로밍 요금이 한참 뒤에 청구되는 이유는 해외 통신사와 정산하는 데 시간이 걸려, 사용 후 1~2개월 뒤에 청구되기 때문입니다.', true, 'GWANGJU', -13802.610908),
    (165, 'ubot.demo.121@example.test', '본인인증 문자가 오지 않아요.', '본인인증 문자가 오지 않아요.', '본인인증 문자가 오지 않아요.', 1, '본인인증 문자가 오지 않아요', '본인인증 문자가 오지 않으면 스팸 차단 앱, 메시지 수신 차단 설정, 문자함 저장 공간을 확인해 주세요. 인증 요청을 짧은 시간에 여러 번 반복하면 본인인증이 잠시 제한될 수 있으니 몇 분 뒤 다시 시도해 주세요.', true, 'SEOUL', -13233.855194),
    (166, 'ubot.demo.122@example.test', '인증번호 문자가 안 와요.', '인증번호 문자가 안 와요.', '인증번호 문자가 안 와요.', 1, '인증번호 문자가 안 와요', '인증번호 문자가 오지 않으면 휴대폰의 신호·문자 수신 상태와 스팸 차단함, 인증 요청 횟수 제한 여부를 확인해 주세요. 일반 문자도 받지 못한다면 회선이나 기기 문제를 점검받아 주세요.', true, 'SEOUL', -13231.891115),
