UPDATE _demo_ql SET created_at = (SELECT now_ts FROM _demo_base) + make_interval(secs => offset_sec);

CREATE TEMP TABLE _demo_faq_log (ql_seq INTEGER NOT NULL, faq_id BIGINT NOT NULL, rank BIGINT NOT NULL, similarity DOUBLE PRECISION NOT NULL) ON COMMIT DROP;

CREATE TEMP TABLE _demo_alert (
    alert_seq INTEGER PRIMARY KEY, region VARCHAR(30) NOT NULL, subject VARCHAR(200),
    question_count INTEGER NOT NULL, window_minutes INTEGER NOT NULL, created_offset DOUBLE PRECISION NOT NULL, updated_offset DOUBLE PRECISION NOT NULL
) ON COMMIT DROP;
CREATE TEMP TABLE _demo_alert_q (alert_seq INTEGER NOT NULL, pos INTEGER NOT NULL, ql_seq INTEGER NOT NULL, question TEXT NOT NULL) ON COMMIT DROP;

DO $$
BEGIN
    IF (SELECT count(*) FROM _demo_ql s JOIN users u ON u.email = s.email AND u.deleted_at IS NULL) <> (SELECT count(*) FROM _demo_ql) THEN
        RAISE EXCEPTION 'Demo users (ubot.demo.101~200) are missing. Run seed-demo-users.sql first.';
    END IF;
    IF (SELECT count(*) FROM _demo_faq_log l JOIN faq f ON f.id = l.faq_id AND f.deleted_at IS NULL) <> (SELECT count(*) FROM _demo_faq_log) THEN
        RAISE EXCEPTION 'Some FAQs referenced by the demo faq_log do not exist.';
    END IF;
END $$;

                          llm_question, ranking_eligible, region, created_at)
SELECT u.user_id, s.user_question, s.sub_question, s.user_text, s.sub_question_index, s.normalized_question,
       s.llm_question, s.ranking_eligible, s.region, s.created_at
FROM _demo_ql s
JOIN users u ON u.email = s.email AND u.deleted_at IS NULL
ORDER BY s.seq;

CREATE TEMP TABLE _demo_ql_map ON COMMIT DROP AS
SELECT s.seq, q.id AS question_log_id, q.created_at
FROM _demo_ql s
JOIN users u ON u.email = s.email AND u.deleted_at IS NULL
JOIN question_log q ON q.user_id = u.user_id
    AND q.user_question = s.user_question
    AND q.sub_question_index = s.sub_question_index
    AND q.created_at = s.created_at;

DO $$
BEGIN
    IF (SELECT count(*) FROM _demo_ql_map) <> (SELECT count(*) FROM _demo_ql)
       OR (SELECT count(DISTINCT seq) FROM _demo_ql_map) <> (SELECT count(*) FROM _demo_ql) THEN
        RAISE EXCEPTION 'Could not map every demo question_log row to its inserted row.';
    END IF;
END $$;

SELECT m.question_log_id, l.faq_id, l.rank, l.similarity, m.created_at
FROM _demo_faq_log l
JOIN _demo_ql_map m ON m.seq = l.ql_seq
ORDER BY m.question_log_id, l.rank;

SELECT a.region, a.subject,
       (SELECT jsonb_agg(jsonb_build_object(
                   'question', aq.question,
                   'occurredAt', jsonb_build_array(
                       EXTRACT(YEAR FROM m.created_at)::int, EXTRACT(MONTH FROM m.created_at)::int,
                       EXTRACT(DAY FROM m.created_at)::int, EXTRACT(HOUR FROM m.created_at)::int,
                       EXTRACT(MINUTE FROM m.created_at)::int, FLOOR(EXTRACT(SECOND FROM m.created_at))::int,
                       (EXTRACT(MICROSECONDS FROM m.created_at)::bigint % 1000000) * 1000),
                   'questionLogId', m.question_log_id) ORDER BY aq.pos)
        FROM _demo_alert_q aq JOIN _demo_ql_map m ON m.seq = aq.ql_seq
        WHERE aq.alert_seq = a.alert_seq),
       a.question_count, a.window_minutes, 'PENDING',
       (SELECT now_ts FROM _demo_base) + make_interval(secs => a.created_offset),
       (SELECT now_ts FROM _demo_base) + make_interval(secs => a.updated_offset)
FROM _demo_alert a
ORDER BY a.alert_seq;

-- 대시보드는 현재 FAQ 버전 이후(question_log.created_at >= faq.updated_at)의 로그만 센다.
-- 로그가 걸리는 FAQ는 모든 시연 로그보다 앞으로 당긴다.
UPDATE faq
SET updated_at = (SELECT now_ts FROM _demo_base) + make_interval(secs => -108000),
    created_at = LEAST(created_at, (SELECT now_ts FROM _demo_base) + make_interval(secs => -108000))
WHERE deleted_at IS NULL AND id IN (SELECT DISTINCT faq_id FROM _demo_faq_log);

-- 사용되지 않은 FAQ 10개는 이틀 이상 전으로 밀어 저사용 FAQ(LOW_USAGE)로 보이게 한다.
DO $$
DECLARE updated INTEGER;
BEGIN
    UPDATE faq f
    SET updated_at = (SELECT now_ts FROM _demo_base) + make_interval(secs => v.offset_sec),
        created_at = (SELECT now_ts FROM _demo_base) + make_interval(secs => v.offset_sec)
    FROM (VALUES
    (9, -183600),
    (45, -201600),
    (51, -219600),
    (67, -237600),
    (75, -255600),
    (84, -273600),
    (268, -291600),
    (301, -309600),
    (314, -327600),
    (328, -345600)
    ) AS v(faq_id, offset_sec)
    WHERE f.id = v.faq_id AND f.deleted_at IS NULL;
    GET DIAGNOSTICS updated = ROW_COUNT;
    IF updated <> 10 THEN
        RAISE EXCEPTION 'Expected to age 10 unused FAQs but updated %.', updated;
    END IF;
END $$;

